import{_ as i,l as s,o as e,c as n,v as r,p as l,x as t,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const P=JSON.parse('{"title":"不完全指定与险象","description":"","frontmatter":{"title":"不完全指定与险象","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dont-care-hazard.md","filePath":"cs/dont-care-hazard.md","lastUpdated":1789023840000}'),p={name:"cs/dont-care-hazard.md"};function E(A,a,u,_,B,m){const o=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="不完全指定与险象" tabindex="-1">不完全指定与险象 <a class="header-anchor" href="#不完全指定与险象" aria-label="Permalink to &quot;不完全指定与险象&quot;">​</a></h1><div class="epigraph"><p>有些输入组合永远不会出现，那些格子可以当 0 也可以当 1；化简可以借它们，却不能假装输入是静止的。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture；Unger 对组合险象的经典处理整理</footer></div><p>上一课<a href="/cs/quine-mccluskey">Quine–McCluskey</a>钉死了完全指定函数的两级合并。本课不重画格雷码网格，也不从「时序电路」另起。缺口有两处，都是卡诺图假装没看见的：有些输入<strong>不会发生</strong>；输入<strong>会变</strong>，中间可能闪一下。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>译码器、指令操作码、后课 FSM 的现态，常常只使用 \\(2^n\\) 中的一部分。那些行在真值表里是 \\(X\\)。若强制填 0，圈变小；把 \\(X\\) 收进圈，乘积项可以更大。缺口之一是：化简必须声明哪些是无关项，合并后这些输入上的值被实现钉死，不能再当「任意」。</p><p>第二缺口：两级与或在输入单比特变化时，若两个相邻 1 分属两个圈且无覆盖两者的圈，输出可能短暂变 0——<strong>静态 1-险象</strong>。卡诺图的最小覆盖可以合法地留下这种洞。功能的静态真值表看不出毛刺。</p><h3 id="无关项不是「别关心对错」" tabindex="-1">无关项不是「别关心对错」 <a class="header-anchor" href="#无关项不是「别关心对错」" aria-label="Permalink to &quot;无关项不是「别关心对错」&quot;">​</a></h3><p>\\(X\\) 只在「不会作为输入出现」时才无关。一旦被圈进去，硬件在那一点有确定值；若将来编码改了、那个组合出现了，行为已经定了。把 \\(X\\) 当成仿真里的不定态传播，是另一套语义，本课不混用。</p><p><span class="marginnote">Harris 用 \\(d\\) 或 \\(X\\) 填图，并说明用质蕴涵项盖住相邻 1 可消静态险象。本课不把动态险象、本质险象的充分条件写完，那些要等多级延迟模型。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>卡诺图上 \\(X\\) 可圈可不圈，选能扩大 2 的幂圈的那些。覆盖完成后，每个 \\(X\\) 变成 0 或 1。对静态 1-险象：凡是差一位的两个 1，应有一个圈同时盖住它们。这可能牺牲「项数最少」。</p>',11)),(e(),l(h,null,{default:t(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20MAP%5B%22%E5%8D%A1%E8%AF%BA%E5%9B%BE%22%5D%20--%3E%20DC%5B%22X%20%E5%8F%AF%E5%B9%B6%E5%85%A5%E5%9C%88%22%5D%0A%20%20MAP%20--%3E%20HAZ%5B%22%E7%9B%B8%E9%82%BB%201%20%E9%A1%BB%E5%85%B1%E5%9C%88%22%5D%0A%20%20DC%20--%3E%20IMPL%5B%22X%20%E8%A2%AB%E5%AE%9E%E7%8E%B0%E9%92%89%E6%AD%BB%22%5D%0A%20%20HAZ%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%9B%86%E5%90%88%E8%AE%BA%E4%B8%8E%E7%A6%BB%E6%95%A3%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课指令译码会把未使用操作码标成 \\(X\\)，综合成更少门；若 CPU 必须对非法操作码陷阱，那些行就不是 \\(X\\)，而是确定的异常路径——<a href="/cs/exception-interrupt-entry">异常入口</a>才接。险象在组合输出直接进时钟敏感点时有害；若输出只在时钟沿被采样，毛刺可能被忽略——那要等<a href="/cs/setup-hold">建立保持时间</a>。本课只承认组合层会闪。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入触发器，不分析多输入同时变的动态险象充分条件，不把模拟电压的中间层当成第三逻辑值。信息与离散课序到此，电路实现尚未开始；下一课改用集合语言，为图、计数、归纳铺底，不再化简门。</p><p>后课默认：不完全指定用于化简；一旦实现，\\(X\\) 消失。静态险象用冗余覆盖消除，若需要。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(X\\) 可帮助合并，实现后不再任意。</li><li>最小 SOP 可能留下静态险象；相邻 1 共圈可消。</li><li>毛刺是否有害，取决于后课是否在时钟沿采样。</li><li>出处：Harris and Harris；组合险象的经典电路教材处理。</li></ul>',7))])}const T=i(p,[["render",E]]);export{P as __pageData,T as default};
